//! LogicView desktop entry.
//!
//! `logicview` opens the Axum UI in a native window. `logicview mcp` stays on
//! stdio and does not open that window. Release builds on Windows use the GUI
//! subsystem, so launching the packaged exe does not create a console.
//!
//! # Startup ownership
//!
//! The desktop module starts the shared engine and local services before loading
//! the page in a native webview. MCP mode runs its own asynchronous entry point
//! and either attaches to that engine or creates a demo engine. Window artwork
//! is generated by the package build script from the existing application icon.

#![cfg_attr(
    all(target_os = "windows", not(debug_assertions)),
    windows_subsystem = "windows"
)]

mod desktop;

use std::io::Write;
use std::net::SocketAddr;
use std::path::PathBuf;

use tracing_subscriber::EnvFilter;

/// Selects desktop or MCP operation and reports startup failures through the appropriate interface.
fn main() {
    init_tracing();
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.first().map(String::as_str) == Some("mcp") {
        std::process::exit(run_mcp(&args));
    }
    if let Err(err) = desktop::open(listen_addr()) {
        desktop::report_error(&err);
        std::process::exit(1);
    }
}

/// Enables application logging using the environment filter or the default verbosity.
fn init_tracing() {
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    let _ = tracing_subscriber::fmt().with_env_filter(filter).try_init();
}

/// Chooses the local UI address, honoring the optional application port setting.
fn listen_addr() -> SocketAddr {
    let port: u16 = std::env::var("LOGICVIEW_PORT")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(4173);
    SocketAddr::from(([127, 0, 0, 1], port))
}

/// Runs the stdio automation interface on an asynchronous runtime and returns its exit status.
fn run_mcp(args: &[String]) -> i32 {
    let attach = args
        .iter()
        .position(|arg| arg == "--attach")
        .and_then(|index| args.get(index + 1))
        .map(PathBuf::from);
    let runtime = match tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
    {
        Ok(runtime) => runtime,
        Err(err) => {
            let _ = writeln!(std::io::stderr(), "logicview mcp: {err}");
            return 1;
        }
    };
    runtime.block_on(logicview_mcp::run_stdio(attach))
}
